var pos = ["好", "优秀", "满意", "赞", "great", "good", "excellent", "love", "happy", "推荐"];
var neg = ["差", "糟", "坏", "失望", "投诉", "bad", "poor", "terrible", "hate", "bug", "错误", "失败"];
var text = String(input.text || "").toLowerCase();
var score = 0;
pos.forEach(function (w) { if (text.indexOf(w) >= 0) score += 1; });
neg.forEach(function (w) { if (text.indexOf(w) >= 0) score -= 1; });
var label = score > 0 ? "positive" : score < 0 ? "negative" : "neutral";
return { score: score, label: label, note: "keyword-based demo sentiment" };
